// Week 2 - Fleet Sensor Simulator
// Plan (Project Plan, Week 2): virtual sensors GPS + battery + speedometer; Implementation
// Plan adds a seat-weight sensor. This node advances a small in-memory fleet each tick and
// emits one telemetry packet per vehicle, which the Edge Filter thins before it is
// published to MQTT (topic fleet/<vehicleID>/telemetry) and shown on the debug sidebar.

const FLEET_SIZE = 3;
const TICK_SECONDS = 1;
const ORIGIN = { lat: -37.8136, lon: 144.9631 }; // Melbourne CBD, for readable coordinates

let fleet = flow.get("fleet");
if (!fleet) {
    fleet = [];
    for (let i = 1; i <= FLEET_SIZE; i++) {
        fleet.push({
            vehicleID: "TAXI-" + String(i).padStart(3, "0"),
            lat: ORIGIN.lat + (Math.random() - 0.5) * 0.02,
            lon: ORIGIN.lon + (Math.random() - 0.5) * 0.02,
            heading: Math.random() * 2 * Math.PI,
            speed: 0,
            batteryLevel: 80 + Math.random() * 20,
            moving: i === 1,        // start one vehicle moving so both states show immediately
            doorsLocked: true,
            seatWeightKg: 0
        });
    }
}

const now = Date.now();
const out = [];

for (const v of fleet) {
    // occasionally flip between parked and driving so the Edge Filter has work to do
    if (Math.random() < 0.15) v.moving = !v.moving;

    if (v.moving) {
        v.speed = 15 + Math.random() * 45;                         // speedometer, km/h
        v.heading += (Math.random() - 0.5) * 0.6;                  // GPS module: gentle turns
        const degPerTick = ((v.speed / 3600) * TICK_SECONDS) / 111; // ~111 km per degree
        v.lat += Math.cos(v.heading) * degPerTick;
        v.lon += Math.sin(v.heading) * degPerTick;
        v.batteryLevel = Math.max(0, v.batteryLevel - 0.05);      // battery monitor: driving draw
        v.seatWeightKg = 55 + Math.random() * 40;                  // seat-weight: passenger aboard
        v.currentState = "driving";
    } else {
        v.speed = 0;
        v.batteryLevel = Math.max(0, v.batteryLevel - 0.005);     // idle draw
        v.seatWeightKg = 0;
        v.currentState = "parked";
    }

    out.push({
        topic: "fleet/" + v.vehicleID + "/telemetry",
        payload: {
            vehicleID: v.vehicleID,
            coordinates: { lat: round(v.lat, 6), lon: round(v.lon, 6) },
            speed: round(v.speed, 2),
            batteryLevel: round(v.batteryLevel, 2),
            currentState: v.currentState,
            seatWeightKg: round(v.seatWeightKg, 2),
            timestamp: now                                          // Unix ms, stamped at the edge
        }
    });
}

flow.set("fleet", fleet);
return [out];

function round(n, dp) { const f = Math.pow(10, dp); return Math.round(n * f) / f; }

// Week 2 - Edge Filter
// ROADMAP Week 2: "drop a reading if parked and GPS delta < 0.0001 degrees".
// Keeps the last forwarded position per vehicle in flow context and compares against it.
// Output 1: forwarded telemetry.  Output 2: suppressed packets (debug visibility only).

const GPS_EPSILON = 0.0001;
const p = msg.payload;

const lastSent = flow.get("lastSent") || {};
const prev = lastSent[p.vehicleID];

const isParked = p.currentState === "parked";
const gpsUnchanged = !!prev
    && Math.abs(p.coordinates.lat - prev.lat) < GPS_EPSILON
    && Math.abs(p.coordinates.lon - prev.lon) < GPS_EPSILON;

if (isParked && gpsUnchanged) {
    msg.suppressedReason = "parked and GPS delta < " + GPS_EPSILON;
    return [null, msg];
}

lastSent[p.vehicleID] = { lat: p.coordinates.lat, lon: p.coordinates.lon };
flow.set("lastSent", lastSent);
return [msg, null];

// Week 2 - Actuator Controller
// Plan (p3/p5): simulated motor controller + door lock that react to command messages.
// Commands arrive over MQTT on fleet/+/command (the Week 6 Dispatch service publishes
// "dispatch") or from the manual inject nodes on this tab.
// Expected command payload: { vehicleID, command }.

const cmd = msg.payload || {};
const fleet = flow.get("fleet") || [];
const v = fleet.find(x => x.vehicleID === cmd.vehicleID);

if (!v) {
    msg.topic = "fleet/actuator/error";
    msg.payload = { error: "unknown vehicleID", received: cmd };
    return msg;
}

let action;
switch (cmd.command) {
    case "dispatch":
        v.moving = true;
        action = "motor controller engaged - vehicle dispatched";
        break;
    case "stop":
        v.moving = false;
        v.speed = 0;
        action = "motor controller disengaged - vehicle stopped";
        break;
    case "lock_doors":
        v.doorsLocked = true;
        action = "door lock actuator - doors locked";
        break;
    case "unlock_doors":
        v.doorsLocked = false;
        action = "door lock actuator - doors unlocked";
        break;
    default:
        action = 'no actuator mapped for command "' + cmd.command + '"';
}

flow.set("fleet", fleet);
msg.topic = "fleet/" + v.vehicleID + "/actuator";
msg.payload = {
    vehicleID: v.vehicleID,
    command: cmd.command,
    action: action,
    actuatorState: { moving: v.moving, doorsLocked: v.doorsLocked, speed: v.speed },
    timestamp: Date.now()
};
return msg;
